import type { IRow } from "../../../metadata-utils/src/types";

type MutationName = "insert" | "update" | "save";

interface IMutationResponse {
  data?: Partial<
    Record<
      MutationName,
      { keys?: { table: string; keys: (string | null)[] }[] | null } | null
    >
  >;
}

/**
 * Returns the primary keys the server reported for the rows of one table in a data mutation
 * (`{ keys { table keys } }`), in the order the rows were sent. Each key has the same shape as a
 * query result, e.g. `{ id: "a1" }` or `{ owner: { name: "x" } }`. Includes keys generated by the
 * database, such as AUTO_ID. Returns an empty list when the response has no keys, for example
 * when the server is older than this field.
 */
export function getMutationKeys(
  response: unknown,
  mutation: MutationName,
  tableId: string
): IRow[] {
  const tableKeys = (response as IMutationResponse)?.data?.[mutation]?.keys;
  const keys = tableKeys?.find((entry) => entry.table === tableId)?.keys;
  return (keys ?? []).map((key) => (key ? JSON.parse(key) : {}));
}
